import { execSync } from "child_process";
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { format } from 'node:util';

const writeOut = (...args: unknown[]): void => {
  process.stdout.write(format(...args) + "\n");
};

const writeErr = (...args: unknown[]): void => {
  process.stderr.write(format(...args) + "\n");
};
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

// Mock logger para evitar dependências ausentes no ambiente de script
const systemLogger = {
  info: (obj: any, msg?: string) => writeOut(JSON.stringify({ level: 'info', ...obj, msg })),
  warn: (obj: any, msg?: string) => writeErr(JSON.stringify({ level: 'warn', ...obj, msg })),
  error: (obj: any, msg?: string) => writeErr(JSON.stringify({ level: 'error', ...obj, msg }))
};

interface DependencyReport {
  installed: boolean;
  vulnerabilities: {
    total: number;
    critical: number;
    high: number;
    moderate: number;
    low: number;
  };
  missing: string[];
  duplicated: string[];
}

/**
 * Script de diagnóstico de dependências do ERP.
 * Verifica pacotes instalados, duplicados e vulnerabilidades.
 */
async function main() {
  writeOut("🔍 Iniciando diagnóstico de dependências do ERP...");

  const report: DependencyReport = {
    installed: true,
    vulnerabilities: { total: 0, critical: 0, high: 0, moderate: 0, low: 0 },
    missing: [],
    duplicated: []
  };

  try {
    // 1. Verificar pacotes não instalados
    writeOut("📦 Verificando pacotes instalados...");
    try {
      execSync("npm list --depth=0", { stdio: 'pipe', cwd: root });
    } catch (error: any) {
      const output = error.stdout.toString();
      const missingMatches = output.match(/UNMET DEPENDENCY (.*)/g);
      if (missingMatches) {
        report.missing = missingMatches.map((m: string) => m.replace("UNMET DEPENDENCY ", "").trim());
        report.installed = false;
      }
    }

    // 2. Verificar vulnerabilidades (npm audit)
    writeOut("🛡️ Verificando vulnerabilidades (npm audit)...");
    try {
      const auditOutput = execSync("npm audit --json", { stdio: 'pipe', cwd: root }).toString();
      const auditData = JSON.parse(auditOutput);

      if (auditData.metadata && auditData.metadata.vulnerabilities) {
        report.vulnerabilities = {
          total: auditData.metadata.totalDependencies || 0,
          ...auditData.metadata.vulnerabilities
        };
      }
    } catch (error: any) {
      // npm audit retorna erro se houver vulnerabilidades
      try {
        const auditData = JSON.parse(error.stdout.toString());
        if (auditData.metadata && auditData.metadata.vulnerabilities) {
          report.vulnerabilities = {
            total: auditData.metadata.totalDependencies || 0,
            ...auditData.metadata.vulnerabilities
          };
        }
      } catch (e) {
        writeErr("⚠️ Não foi possível analisar o JSON do npm audit.");
      }
    }

    // 3. Gerar relatório visual
    writeOut("\n========================================");
    writeOut("        DEPENDENCY CHECK REPORT         ");
    writeOut("========================================");

    if (report.installed && report.missing.length === 0) {
      writeOut("✅ Dependencies: OK (All installed)");
    } else {
      writeOut(`❌ Dependencies: MISSING (${report.missing.length} packages)`);
      report.missing.forEach(pkg => writeOut(`   - ${pkg}`));
    }

    const vulns = report.vulnerabilities;
    const totalVulns = vulns.critical + vulns.high + vulns.moderate + vulns.low;

    if (totalVulns === 0) {
      writeOut("✅ Vulnerabilities: 0 (Safe)");
    } else {
      writeOut(`⚠️ Vulnerabilities: ${totalVulns} found`);
      if (vulns.critical > 0) writeOut(`   - Critical: ${vulns.critical} 🚨`);
      if (vulns.high > 0) writeOut(`   - High: ${vulns.high} 🟠`);
      if (vulns.moderate > 0) writeOut(`   - Moderate: ${vulns.moderate} 🟡`);
      if (vulns.low > 0) writeOut(`   - Low: ${vulns.low} 🔵`);
    }

    writeOut("========================================\n");

    // 4. Registrar no Logger
    systemLogger.info({
      module: "dependency-check",
      status: totalVulns > 0 || !report.installed ? "warning" : "success",
      missingCount: report.missing.length,
      vulnerabilities: report.vulnerabilities
    }, "Diagnóstico de dependências concluído");

  } catch (error: any) {
    systemLogger.error({
      module: "dependency-check",
      error: error.message
    }, "Falha crítica no diagnóstico de dependências");
    writeErr("❌ Falha crítica:", error.message);
    process.exit(1);
  }
}

main();

#!/usr/bin/env node

/**
 * Deploy Script for GRS ERP
 * 
 * Script para preparação e deploy do sistema em produção
 */

import { execSync } from 'child_process';
import { readFileSync, writeFileSync, existsSync } from 'fs';
import { join } from 'path';
import { format } from 'node:util';

const writeOut = (...args: unknown[]): void => {
  process.stdout.write(format(...args) + "\n");
};

const writeErr = (...args: unknown[]): void => {
  process.stderr.write(format(...args) + "\n");
};
interface DeployConfig {
  environment: 'staging' | 'production';
  buildPath: string;
  backupPath: string;
  healthCheckUrl: string;
  maxRetries: number;
}

class DeployManager {
  private config: DeployConfig;

  constructor() {
    this.config = {
      environment: (process.env.DEPLOY_ENV as any) || 'staging',
      buildPath: './dist',
      backupPath: './backups',
      healthCheckUrl: process.env.HEALTH_CHECK_URL || 'http://localhost:3000/system/health',
      maxRetries: 5
    };
  }

  /**
   * Executa o deploy completo
   */
  async deploy(): Promise<void> {
    writeOut('🚀 Iniciando deploy do GRS ERP');
    writeOut(`📍 Ambiente: ${this.config.environment}`);
    writeOut(`⏰ Início: ${new Date().toISOString()}`);

    try {
      // 1. Validações pré-deploy
      await this.preDeployChecks();

      // 2. Backup do sistema atual
      await this.backupCurrentSystem();

      // 3. Build do projeto
      await this.buildProject();

      // 4. Otimizações de banco
      await this.optimizeDatabase();

      // 5. Deploy dos arquivos
      await this.deployFiles();

      // 6. Health check
      await this.performHealthCheck();

      // 7. Pós-deploy
      await this.postDeployActions();

      writeOut('✅ Deploy concluído com sucesso!');
      writeOut(`⏰ Término: ${new Date().toISOString()}`);

    } catch (error: unknown) {
      writeErr('❌ Falha no deploy:', error instanceof Error ? error.message : String(error));

      // Tentar restaurar backup em caso de falha
      await this.rollback();

      process.exit(1);
    }
  }

  /**
   * Validações pré-deploy
   */
  private async preDeployChecks(): Promise<void> {
    writeOut('🔍 Executando validações pré-deploy...');

    // Verificar variáveis de ambiente
    const requiredEnvVars = [
      'NODE_ENV',
      'DATABASE_URL',
      'JWT_ACCESS_SECRET',
      'JWT_REFRESH_SECRET',
    ];

    const missingVars = requiredEnvVars.filter(varName => !process.env[varName]);

    if (missingVars.length > 0) {
      throw new Error(`Variáveis de ambiente obrigatórias não encontradas: ${missingVars.join(', ')}`);
    }

    // Verificar se está em produção
    if (this.config.environment === 'production') {
      const unsafeVars = [
        'JWT_ACCESS_SECRET',
        'JWT_REFRESH_SECRET',
        'SESSION_SECRET'
      ];

      const unsafeVarsFound = unsafeVars.filter(varName => {
        const value = process.env[varName];
        return value && (
          value.includes('default') ||
          value.includes('secret') ||
          value.includes('change') ||
          value.length < 20
        );
      });

      if (unsafeVarsFound.length > 0) {
        throw new Error(`Variáveis de ambiente inseguras detectadas: ${unsafeVarsFound.join(', ')}`);
      }
    }

    // Verificar dependências
    writeOut('📦 Verificando dependências...');
    execSync('npm ci --production', { stdio: 'inherit' });

    // Type checking
    writeOut('🔧 Verificando tipos TypeScript...');
    execSync('npm run type-check', { stdio: 'inherit' });

    // Linting
    writeOut('🧹 Verificando código com ESLint...');
    execSync('npm run lint', { stdio: 'inherit' });

    // Testes
    writeOut('🧪 Executando testes...');
    execSync('npm run test', { stdio: 'inherit' });

    writeOut('✅ Validações pré-deploy concluídas');
  }

  /**
   * Backup do sistema atual
   */
  private async backupCurrentSystem(): Promise<void> {
    writeOut('💾 Criando backup do sistema atual...');

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    const backupDir = join(this.config.backupPath, `backup-${timestamp}`);

    // Criar diretório de backup
    execSync(`mkdir -p ${backupDir}`, { stdio: 'inherit' });

    // Backup do banco de dados
    if (process.env.DATABASE_URL) {
      writeOut('🗄️ Fazendo backup do banco de dados...');
      const backupFile = join(backupDir, 'database.sql');

      try {
        execSync(
          `mysqldump --single-transaction --routines --triggers "${process.env.DB_NAME}" > "${backupFile}"`,
          { stdio: 'inherit' }
        );
        writeOut('✅ Backup do banco criado');
      } catch (error) {
        writeErr('⚠️ Falha no backup do banco:', error);
      }
    }

    // Backup dos arquivos de configuração
    const configFiles = [
      '.env',
      'server/config/env.ts'
    ];

    configFiles.forEach(file => {
      if (existsSync(file)) {
        execSync(`cp "${file}" "${backupDir}/"`, { stdio: 'inherit' });
      }
    });

    // Salvar metadata do deploy
    const deployInfo = {
      timestamp: new Date().toISOString(),
      environment: this.config.environment,
      version: this.getCurrentVersion(),
      gitCommit: this.getGitCommit(),
      nodeVersion: process.version,
      platform: process.platform
    };

    writeFileSync(
      join(backupDir, 'deploy-info.json'),
      JSON.stringify(deployInfo, null, 2)
    );

    writeOut(`✅ Backup criado em: ${backupDir}`);
  }

  /**
   * Build do projeto
   */
  private async buildProject(): Promise<void> {
    writeOut('🔨 Build do projeto...');

    // Limpar build anterior
    if (existsSync(this.config.buildPath)) {
      execSync(`rm -rf ${this.config.buildPath}`, { stdio: 'inherit' });
    }

    // Build de produção
    process.env.NODE_ENV = this.config.environment;
    execSync('npm run build', { stdio: 'inherit' });

    writeOut('✅ Build concluído');
  }

  /**
   * Otimizações do banco de dados
   */
  private async optimizeDatabase(): Promise<void> {
    writeOut('⚡ Otimizando banco de dados...');

    try {
      // Criar índices recomendados
      execSync('npm run optimize:db', { stdio: 'inherit' });

      // Analisar tabelas
      execSync('npm run db:analyze', { stdio: 'inherit' });

      writeOut('✅ Banco de dados otimizado');
    } catch (error) {
      writeErr('⚠️ Falha na otimização do banco:', error);
    }
  }

  /**
   * Deploy dos arquivos
   */
  private async deployFiles(): Promise<void> {
    writeOut('📁 Deploy dos arquivos...');

    // Copiar arquivos buildados
    execSync(`cp -r ${this.config.buildPath}/* ./`, { stdio: 'inherit' });

    // Ajustar permissões
    execSync('chmod +x server/index.js', { stdio: 'inherit' });

    // Instalar dependências de produção
    execSync('npm ci --production', { stdio: 'inherit' });

    writeOut('✅ Arquivos deployados');
  }

  /**
   * Health check pós-deploy
   */
  private async performHealthCheck(): Promise<void> {
    writeOut('🏥 Executando health check...');

    for (let attempt = 1; attempt <= this.config.maxRetries; attempt++) {
      try {
        writeOut(`Tentativa ${attempt}/${this.config.maxRetries}`);

        const response = await fetch(this.config.healthCheckUrl);

        if (response.ok) {
          const health = await response.json();

          if (health.status === 'ok') {
            writeOut('✅ Health check passed');
            return;
          }
        }

        throw new Error(`Health check failed: ${response.status}`);

      } catch (error) {
        writeErr(`Tentativa ${attempt} falhou:`, error instanceof Error ? error.message : String(error));

        if (attempt < this.config.maxRetries) {
          const delay = Math.min(5000 * attempt, 30000); // Max 30 segundos
          writeOut(`Aguardando ${delay}ms antes da próxima tentativa...`);
          await new Promise(resolve => setTimeout(resolve, delay));
        }
      }
    }

    throw new Error('Health check falhou após todas as tentativas');
  }

  /**
   * Ações pós-deploy
   */
  private async postDeployActions(): Promise<void> {
    writeOut('🎯 Executando ações pós-deploy...');

    // Limpar cache
    try {
      execSync('npm run cache:clear', { stdio: 'inherit' });
    } catch (error) {
      writeErr('⚠️ Falha ao limpar cache:', error);
    }

    // Reiniciar serviços se necessário
    if (this.config.environment === 'production') {
      try {
        execSync('pm2 reload erp-server', { stdio: 'inherit' });
        writeOut('✅ Serviços reiniciados');
      } catch (error) {
        writeErr('⚠️ Falha ao reiniciar serviços:', error);
      }
    }

    // Notificar deploy
    await this.notifyDeploySuccess();

    writeOut('✅ Ações pós-deploy concluídas');
  }

  /**
   * Rollback em caso de falha
   */
  private async rollback(): Promise<void> {
    writeOut('🔄 Executando rollback...');

    try {
      // Encontrar backup mais recente
      const backups = execSync(`ls -1t ${this.config.backupPath}`, { encoding: 'utf8' })
        .split('\n')
        .filter(Boolean);

      if (backups.length === 0) {
        writeErr('⚠️ Nenhum backup encontrado para rollback');
        return;
      }

      const latestBackup = join(this.config.backupPath, backups[0]);

      // Restaurar arquivos
      execSync(`cp -r ${latestBackup}/* ./`, { stdio: 'inherit' });

      // Restaurar banco se disponível
      const dbBackup = join(latestBackup, 'database.sql');
      if (existsSync(dbBackup)) {
        execSync(`mysql "${process.env.DB_NAME}" < "${dbBackup}"`, { stdio: 'inherit' });
      }

      writeOut('✅ Rollback concluído');

    } catch (error) {
      writeErr('❌ Falha no rollback:', error instanceof Error ? error.message : String(error));
    }
  }

  /**
   * Notificar sucesso do deploy
   */
  private async notifyDeploySuccess(): Promise<void> {
    writeOut('📢 Notificando deploy...');

    const deployInfo = {
      environment: this.config.environment,
      version: this.getCurrentVersion(),
      timestamp: new Date().toISOString(),
      gitCommit: this.getGitCommit(),
      success: true
    };

    // Aqui poderia integrar com Slack, email, etc.
    writeOut('📧 Deploy notificado:', JSON.stringify(deployInfo, null, 2));
  }

  /**
   * Obter versão atual do sistema
   */
  private getCurrentVersion(): string {
    try {
      const packageJson = readFileSync('./package.json', 'utf8');
      return JSON.parse(packageJson).version || 'unknown';
    } catch {
      return 'unknown';
    }
  }

  /**
   * Obter commit atual do Git
   */
  private getGitCommit(): string {
    try {
      return execSync('git rev-parse HEAD', { encoding: 'utf8' }).trim();
    } catch {
      return 'unknown';
    }
  }
}

// Executar deploy
if (require.main === module) {
  const deployManager = new DeployManager();
  deployManager.deploy().catch(error => {
    writeErr('❌ Erro fatal no deploy:', error);
    process.exit(1);
  });
}

export { DeployManager };

/**
 * Simulação operacional: 10 pedidos, 3 cargas, conferência, baixa parcial e total.
 * Objetivo: verificar se os fluxos (pedido → conferência → carga → baixa) funcionam sem erro.
 *
 * Pré-requisitos: banco configurado (.env), ao menos 1 vendedor, clientes e produtos.
 * Uso: npx tsx scripts/simular-operacao.ts (a partir da raiz do projeto)
 */
import "dotenv/config";
import * as db from "../server/db";
import { format } from 'node:util';

const writeOut = (...args: unknown[]): void => {
  process.stdout.write(format(...args) + "\n");
};

const writeErr = (...args: unknown[]): void => {
  process.stderr.write(format(...args) + "\n");
};
const traceId = `sim-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

async function main() {
  const conn = await db.getDb();
  if (!conn) {
    writeErr("[simular-operacao] Banco indisponível. Configure .env (DB_HOST, DB_USER, DB_PASSWORD, DB_NAME).");
    process.exit(1);
  }

  const vendedores = await db.getAllVendedores();
  const clientes = await db.getAllClientes();
  const produtos = await db.getAllProdutosComPrecoVigente(new Date());

  if (!vendedores.length) {
    writeErr("[simular-operacao] Nenhum vendedor. Rode npm run seed:admin.");
    process.exit(1);
  }
  if (!clientes.length) {
    writeErr("[simular-operacao] Nenhum cliente. Cadastre clientes ou rode seed de massa.");
    process.exit(1);
  }
  if (!produtos.length) {
    writeErr("[simular-operacao] Nenhum produto. Cadastre produtos.");
    process.exit(1);
  }

  const vendedorId = vendedores[0].id;
  const clienteList = (clientes as any[]) || [];
  const produtoList = (produtos as any[]) || [];

  writeOut("[simular-operacao] Iniciando simulação. traceId:", traceId);

  // --- 1) Criar 10 pedidos ---
  const pedidoIds: number[] = [];
  for (let i = 0; i < 10; i++) {
    const cliente = clienteList[i % clienteList.length] as any;
    const numero = await db.getNextCounter("pedidos");
    const total = 100 + (i % 5) * 50;
    const pedidoData: db.InsertPedido = {
      numero,
      vendedorId,
      clienteId: cliente.id,
      clienteNome: cliente.nome ?? "Cliente Simulação",
      clienteTelefone: cliente.telefone ?? null,
      subtotal: String(total),
      desconto: "0",
      frete: "0",
      total: String(total),
      status: "GERADO",
    } as any;
    const insertResult = await db.createPedido(pedidoData);
    const pedidoId = (insertResult as any)[0]?.insertId ?? (insertResult as any).insertId;
    if (!pedidoId) throw new Error("Falha ao obter id do pedido");
    pedidoIds.push(pedidoId);

    const prod = produtoList[i % Math.max(1, produtoList.length)] as any;
    const itens: db.InsertItemPedido[] = [
      {
        pedidoId,
        tipo: prod?.id ? "CATALOGO" : "LIVRE",
        produtoId: prod?.id ?? null,
        descricao: prod?.descricao ?? `Item sim ${i + 1}`,
        quantidade: 1 + (i % 2),
        valorUnitario: String(total / (1 + (i % 2))),
        custo: "0",
        prazoGarantia: 90,
      } as any,
    ];
    await db.createItensPedido(itens);
    writeOut(`  Pedido #${numero} criado (id ${pedidoId})`);
  }

  // --- 2) Conferência dos 10 pedidos ---
  await (conn as any).transaction(async (tx: any) => {
    for (const pedidoId of pedidoIds) {
      await db.marcarPedidoConferidoAudit(tx, {
        pedidoId,
        actorVendedorId: vendedorId,
        traceId,
      });
    }
  });
  writeOut("  Conferência: 10 pedidos marcados como CONFERIDO.");

  // --- 3) Criar 3 cargas ---
  const dataEntrega = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000);
  const r1 = await db.createCarga({ cidadeRota: "Cidade A", dataEntrega }, pedidoIds.slice(0, 4));
  const r2 = await db.createCarga({ cidadeRota: "Cidade B", dataEntrega }, pedidoIds.slice(4, 7));
  const r3 = await db.createCarga({ cidadeRota: "Cidade C", dataEntrega }, pedidoIds.slice(7, 10));
  const cargaIds = [(r1 as any).id, (r2 as any).id, (r3 as any).id].filter(Boolean);
  writeOut("  Cargas criadas:", cargaIds.length);

  // Liberar cargas para rota (EM_ROTA)
  for (const cargaId of cargaIds) {
    await db.fecharCarga(cargaId);
  }
  writeOut("  Cargas liberadas para rota (EM_ROTA).");

  // --- 4) Baixa parcial e total ---
  const carga1Detail = await db.getCargaById(cargaIds[0]);
  const pedidosCarga = (carga1Detail as any)?.pedidos ?? [];
  const pedidoCargaIds = pedidosCarga.map((p: any) => p.pedidoCargaId).filter(Boolean);

  if (pedidoCargaIds.length >= 1) {
    await db.baixarPedidoCarga(pedidoCargaIds[0], {
      entradaForma: "PIX",
      entradaValor: 50,
      segundaForma: "DINHEIRO",
      segundaValor: 50,
    });
    writeOut("  Baixa parcial (1 pedido) realizada.");
  }
  if (pedidoCargaIds.length >= 2) {
    await db.baixarPedidoCarga(pedidoCargaIds[1], {
      entradaForma: "DINHEIRO",
      entradaValor: 150,
    });
    writeOut("  Baixa total (1 pedido) realizada.");
  }
  if (pedidoCargaIds.length >= 3) {
    await db.baixarPedidoCarga(pedidoCargaIds[2], {
      entradaForma: "PIX",
      entradaValor: 200,
    });
    writeOut("  Segunda baixa total realizada.");
  }

  // Tentativa de segunda baixa no mesmo pedido (deve falhar)
  try {
    await db.baixarPedidoCarga(pedidoCargaIds[0], { entradaForma: "PIX", entradaValor: 100 });
    writeOut("  [AVISO] Segunda baixa no mesmo pedido não foi bloqueada.");
  } catch (e: any) {
    if (e?.message?.includes("já foi baixado") || e?.message?.includes("já está entregue")) {
      writeOut("  Segunda baixa indevida corretamente bloqueada.");
    } else {
      writeErr("  Erro inesperado ao tentar segunda baixa:", e?.message);
    }
  }

  writeOut("[simular-operacao] Simulação concluída sem erro.");
}

main().catch((e) => {
  writeErr("[simular-operacao] Erro:", e?.message ?? e);
  process.exit(1);
});

