/**
 * Script para instalar dependências do Leo Operator Total
 * 
 * Instala as bibliotecas necessárias para as fases de automação:
 * - robotjs (controle de mouse e teclado)
 * - screenshot-desktop (captura de tela)
 * - tesseract.js (OCR)
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import { format } from 'node:util';

const writeOut = (...args: unknown[]): void => {
  process.stdout.write(format(...args) + "\n");
};

const writeErr = (...args: unknown[]): void => {
  process.stderr.write(format(...args) + "\n");
};
const execAsync = promisify(exec);

interface Dependency {
  name: string;
  version?: string;
  description: string;
  phase: string;
}

const dependencies: Dependency[] = [
  {
    name: 'screenshot-desktop',
    description: 'Captura de tela',
    phase: 'FASE 5 - Captura de tela'
  },
  {
    name: 'tesseract.js',
    description: 'OCR para leitura de tela',
    phase: 'FASE 6 - OCR para leitura de tela'
  }
];

/**
 * Instala uma dependência específica
 */
async function installDependency(dep: Dependency): Promise<boolean> {
  try {
    writeOut(`\n📦 Instalando ${dep.name}...`);
    writeOut(`   ${dep.description}`);
    writeOut(`   ${dep.phase}`);
    
    const versionSpecifier = dep.version ? `@${dep.version}` : '';
    const command = `npm install ${dep.name}${versionSpecifier}`;
    
    writeOut(`   Comando: ${command}`);
    
    const { stdout, stderr } = await execAsync(command);
    
    if (stderr && !stderr.includes('warn')) {
      writeErr(`   ⚠️  Warnings: ${stderr}`);
    }
    
    writeOut(`   ✅ ${dep.name} instalado com sucesso!`);
    return true;
  } catch (error) {
    writeErr(`   ❌ Erro ao instalar ${dep.name}:`);
    writeErr(`      ${error instanceof Error ? error.message : error}`);
    return false;
  }
}

/**
 * Verifica se uma dependência já está instalada
 */
async function checkDependency(dep: Dependency): Promise<boolean> {
  try {
    const { stdout } = await execAsync(`npm list ${dep.name} --depth=0`);
    return stdout.includes(dep.name);
  } catch {
    return false;
  }
}

/**
 * Função principal
 */
async function main(): Promise<any> {
  writeOut('🤖 LEO - Instalação de Dependências para Operador Total');
  writeOut('=' .repeat(60));
  
  writeOut('\n📋 Verificando dependências necessárias...');
  
  const results: { dependency: string; installed: boolean; alreadyExisted: boolean }[] = [];
  
  for (const dep of dependencies) {
    writeOut(`\n🔍 Verificando ${dep.name}...`);
    
    const alreadyExists = await checkDependency(dep);
    
    if (alreadyExists) {
      writeOut(`   ✅ ${dep.name} já está instalado`);
      results.push({ dependency: dep.name, installed: true, alreadyExisted: true });
    } else {
      const installed = await installDependency(dep);
      results.push({ dependency: dep.name, installed, alreadyExisted: false });
    }
  }
  
  // Resumo
  writeOut('\n' + '='.repeat(60));
  writeOut('📊 RESUMO DA INSTALAÇÃO');
  writeOut('='.repeat(60));
  
  let successCount = 0;
  let alreadyCount = 0;
  
  for (const result of results) {
    const dep = dependencies.find(d => d.name === result.dependency);
    const status = result.installed ? '✅' : '❌';
    const note = result.alreadyExisted ? ' (já existia)' : '';
    
    writeOut(`${status} ${result.dependency}${note}`);
    writeOut(`   ${dep?.description}`);
    
    if (result.installed) {
      successCount++;
      if (result.alreadyExisted) alreadyCount++;
    }
  }
  
  writeOut('\n📈 ESTATÍSTICAS:');
  writeOut(`   Total de dependências: ${dependencies.length}`);
  writeOut(`   Instaladas com sucesso: ${successCount}`);
  writeOut(`   Já existiam: ${alreadyCount}`);
  writeOut(`   Novas instalações: ${successCount - alreadyCount}`);
  writeOut(`   Falhas: ${dependencies.length - successCount}`);
  
  if (successCount === dependencies.length) {
    writeOut('\n🎉 Todas as dependências estão prontas!');
    writeOut('\n🚀 Próximos passos:');
    writeOut('   1. Reinicie o servidor de desenvolvimento');
    writeOut('   2. As próximas fases do Leo já podem ser implementadas');
    writeOut('   3. Execute: npm run dev');
  } else {
    writeOut('\n⚠️  Algumas dependências falharam na instalação.');
    writeOut('   Verifique os erros acima e tente manualmente se necessário.');
  }
  
  writeOut('\n🔧 Dependências para fases futuras:');
  writeOut('   FASE 4: robotjs - Controle de mouse e teclado');
  writeOut('   FASE 5: screenshot-desktop - Captura de tela');
  writeOut('   FASE 6: tesseract.js - OCR para leitura de tela');
}

// Executar script
if (require.main === module) {
  main().catch((error) => writeErr(error instanceof Error ? error.message : String(error)));
}

export { installDependency, checkDependency, dependencies };

